mapper.update:
update database_catalog d
set asset_external_id = (
      select min(a.external_id) from dbaas_asset a
      where a.db_name = d.name and a.last_seen_run_id = #{runId}
    ), active = true
where d.asset_external_id is not null
  and not exists (
    select 1 from dbaas_asset a
    where a.external_id = d.asset_external_id and a.db_name = d.name
      and a.last_seen_run_id = #{runId}
  )
  and exists (
    select 1 from dbaas_asset a
    where a.db_name = d.name and a.last_seen_run_id = #{runId}
  )

mapper.select:
select a.external_id, a.db_name, a.raw_data
from dbaas_asset a
join database_catalog d on d.name = a.db_name
where a.last_seen_run_id = #{runId}
  and d.asset_external_id is not null
  and not exists (
    select 1 from dbaas_asset prior_asset
    where prior_asset.external_id = d.asset_external_id and prior_asset.db_name = d.name
      and prior_asset.last_seen_run_id = #{runId}
  )
  and a.external_id = (
    select min(candidate.external_id) from dbaas_asset candidate
    where candidate.db_name = d.name and candidate.last_seen_run_id = #{runId}
  )
